1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Computes an owner's {@code checkDigit} &mdash; a single Luhn check digit (0-9) over the digits
5	 * contained in the owner's {@code customerCode}.
6	 *
7	 * <p>Non-digit characters (the region letters and the separator in {@code '<REGION>-<HASH8>'}, and
8	 * the {@code A-F} hex letters of the hash) are ignored. The digits are processed right-to-left,
9	 * doubling every second digit starting with the rightmost;
10	 * a doubled value above nine has nine subtracted. The check digit is the amount that brings the
11	 * running sum up to the next multiple of ten.
12	 */
13	public final class CheckDigit {
14	
15	    private CheckDigit() {
16	    }
17	
18	    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
19	    public static int of(String s) {
20	        int sum = 0;
21	        boolean dbl = true;
22	        for (int i = s.length() - 1; i >= 0; i--) {
23	            char c = s.charAt(i);
24	            if (c < '0' || c > '9') {
25	                continue;
26	            }
27	            int d = c - '0';
28	            if (dbl) {
29	                d *= 2;
30	                if (d > 9) {
31	                    d -= 9;
32	                }
33	            }
34	            sum += d;
35	            dbl = !dbl;
36	        }
37	        return (10 - (sum % 10)) % 10;
38	    }
39	}
