1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Derives fiscal-year values from a date. The fiscal year runs 1 July to 30 June and is identified
8	 * by the calendar year in which it ends, so 1 July 2025 to 30 June 2026 is fiscal year 2026 and its
9	 * label is {@code FY26}.
10	 *
11	 * <p>Fed the owner's persisted (business-day-adjusted) registration date, this is the single source
12	 * of truth for the {@code fiscalYear} response field, the membership number's year segment and the
13	 * tenure count in {@link MembershipLevel}, so they always agree.
14	 *
15	 * <p>Kept as a standalone class (not a method on {@link OwnerMapper}) so MapStruct does not mistake
16	 * it for an implicit mapping method.
17	 */
18	public final class FiscalYear {
19	
20	    private FiscalYear() {
21	    }
22	
23	    /**
24	     * The fiscal-year ordinal for {@code date}: the calendar year in which its fiscal year (1 July
25	     * to 30 June) ends. Dates in July or later belong to the fiscal year ending the next calendar
26	     * year; earlier dates belong to the one ending in the same calendar year.
27	     */
28	    public static int ordinal(LocalDate date) {
29	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
30	    }
31	
32	    /** The two-digit year segment of {@code date}'s fiscal year (its ordinal modulo 100). */
33	    public static int yearSegment(LocalDate date) {
34	        return ordinal(date) % 100;
35	    }
36	
37	    /** The fiscal-year label {@code FY<YY>} for {@code date}, e.g. {@code FY26}. */
38	    public static String label(LocalDate date) {
39	        return String.format("FY%02d", yearSegment(date));
40	    }
41	
42	    /**
43	     * The number of whole fiscal years elapsed from {@code from} to {@code to}, i.e. the difference
44	     * of their fiscal-year ordinals. Zero when both fall in the same fiscal year.
45	     */
46	    public static int elapsed(LocalDate from, LocalDate to) {
47	        return ordinal(to) - ordinal(from);
48	    }
49	}
