1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * The owner's <em>current</em> primary identifier &mdash; the single value that downstream
7	 * consumers (such as the {@code OWNER_CREATED} audit event) quote to name an owner.
8	 *
9	 * <p>Today that identifier is the {@code customerCode}. When the customer code is later unified into
10	 * a {@code memberId}, only this one method changes to return the {@code memberId}, and every
11	 * consumer routed through it (the create audit event, in particular) carries the new identifier
12	 * automatically &mdash; no consumer hard-codes {@link Owner#getCustomerCode()} directly.
13	 *
14	 * <p>Kept as a standalone class (like {@link MembershipLevel}) so MapStruct does not mistake it for
15	 * an implicit mapping method, and so there is a single source of truth for "the owner's identifier".
16	 */
17	public final class PrimaryIdentifier {
18	
19	    private PrimaryIdentifier() {
20	    }
21	
22	    /** The owner's current primary identifier: the {@code customerCode}. */
23	    public static String of(Owner owner) {
24	        return owner.getCustomerCode();
25	    }
26	}
