1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Set;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's marketing segment, formatted {@code '<TIER>_<AREA>'}.
9	 *
10	 * <p>TIER is {@code PREMIUM} when the owner's {@link MembershipLevel} is 3 or more, otherwise
11	 * {@code STANDARD}. AREA is {@code METRO} when the owner's {@link Locality} is a known region
12	 * (NSW, VIC or QLD), otherwise {@code REGIONAL}. So the segment is one of {@code PREMIUM_METRO},
13	 * {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
14	 *
15	 * <p>Kept as a standalone class (not a method on {@link OwnerMapper}) so MapStruct does not
16	 * mistake it for an implicit mapping method, mirroring {@link Locality} and {@link Timezone}.
17	 */
18	public final class OwnerSegment {
19	
20	    /** The known regions whose locality counts as METRO. */
21	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
22	
23	    private OwnerSegment() {
24	    }
25	
26	    /** The {@code '<TIER>_<AREA>'} segment for {@code owner}. */
27	    public static String of(Owner owner) {
28	        String tier = MembershipLevel.of(owner) >= 3 ? "PREMIUM" : "STANDARD";
29	        String area = METRO_REGIONS.contains(Locality.ofCustomerCode(owner.getCustomerCode()))
30	            ? "METRO" : "REGIONAL";
31	        return tier + "_" + area;
32	    }
33	}
