1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's membership points and numeric membership level from their persisted fields.
9	 *
10	 * <p>Points start at 0; add 2 when an email is present; add 1 when {@code namesakeCount} is 0; add
11	 * 2 for a household of 3 or more; add 3 for tenure of at least one elapsed fiscal year. Tenure is
12	 * the number of whole fiscal years (starting 1 July) from the registration date to today, so a
13	 * newly created owner has zero tenure and never earns the tenure points: a fresh owner tops out at
14	 * 5 points.
15	 *
16	 * <p>The membership level maps the points: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
17	 *
18	 * <p>A membership-level cap may be recorded on the owner (see {@code membershipLevelCap}): a newly
19	 * created owner joining an existing household cannot exceed one level above the highest membership
20	 * level already held in that household. When such a cap is present the derived level is clamped to
21	 * it; with no cap (no existing household member) the points-derived level stands.
22	 *
23	 * <p>Kept as a standalone class (not a method on {@link OwnerMapper}) so MapStruct does not
24	 * mistake it for an implicit mapping method. Single source of truth so the response DTO and
25	 * the create audit line agree on the points and level.
26	 */
27	public final class MembershipLevel {
28	
29	    private MembershipLevel() {
30	    }
31	
32	    /** The membership points for {@code owner}. */
33	    public static int points(Owner owner) {
34	        int points = 0;
35	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
36	            points += 2;
37	        }
38	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
39	            points += 1;
40	        }
41	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
42	            points += 2;
43	        }
44	        if (owner.getRegistrationDate() != null
45	                && FiscalYear.elapsed(owner.getRegistrationDate(), LocalDate.now()) >= 1) {
46	            points += 3;
47	        }
48	        return points;
49	    }
50	
51	    /**
52	     * The membership level (1 to 4) for {@code owner}, derived from {@link #points(Owner)} and
53	     * clamped to the owner's recorded {@code membershipLevelCap} when one is present.
54	     */
55	    public static int of(Owner owner) {
56	        int level = fromPoints(points(owner));
57	        Integer cap = owner.getMembershipLevelCap();
58	        if (cap != null && level > cap) {
59	            return cap;
60	        }
61	        return level;
62	    }
63	
64	    /** The uncapped membership level for the given points total. */
65	    private static int fromPoints(int points) {
66	        if (points <= 1) {
67	            return 1;
68	        }
69	        if (points <= 3) {
70	            return 2;
71	        }
72	        if (points <= 5) {
73	            return 3;
74	        }
75	        return 4;
76	    }
77	}
