1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.mapper.Locality;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Assigns the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where REGION is the
13	 * region code derived from the owner's postcode (via {@link Locality}, postcode first then city) and
14	 * HASH8 is the first 8 upper-case hex characters of SHA-256 over the normalised telephone
15	 * concatenated with the last name. There is no per-city sequence number.
16	 *
17	 * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code '-<n>'}
18	 * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
19	 * always end up with distinct customer codes. Mutates the built owner in place before it is saved.
20	 */
21	public class AssignCustomerCode {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
24	        String region = Locality.of(owner.getCity(), owner.getPostcode());
25	        String hash8 = OwnerIdentity.customerHash(owner.getTelephone(), owner.getLastName());
26	        String base = region + "-" + hash8;
27	
28	        Set<String> taken = new HashSet<>();
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.getCustomerCode() != null) {
31	                taken.add(existing.getCustomerCode());
32	            }
33	        }
34	
35	        String code = base;
36	        for (int n = 2; taken.contains(code); n++) {
37	            code = base + "-" + n;
38	        }
39	        owner.setCustomerCode(code);
40	    }
41	}
