1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Derives an owner's {@code identityKey} &mdash; the single value all duplicate detection is now
10	 * expressed through.
11	 *
12	 * <p>The key is the lower-case hex SHA-256 of
13	 * {@code normalizedTelephone + '|' + (email or empty, lower-cased) + '|' + soundex(lastName)}.
14	 * Two owners are duplicates only when their <em>whole</em> keys are equal: because the telephone is
15	 * part of the hashed input, two owners sharing a last name and postcode but with different
16	 * telephones have different keys and are both allowed &mdash; the second is recorded as a soft match
17	 * rather than rejected.
18	 */
19	public final class OwnerIdentity {
20	
21	    private OwnerIdentity() {
22	    }
23	
24	    /**
25	     * Builds the identity key from an owner's parts: the full lower-case hex SHA-256 of
26	     * {@code normalizedTelephone + '|' + email + '|' + soundex(lastName)}. The telephone is expected
27	     * to already be in E.164 form (as stored); the email is lower-cased and a null/blank email
28	     * contributes an empty segment; the last name contributes its Soundex code.
29	     */
30	    public static String key(String telephone, String email, String lastName) {
31	        String tel = telephone == null ? "" : telephone;
32	        String em = (email == null || email.isBlank()) ? "" : email.trim().toLowerCase(Locale.ROOT);
33	        String raw = tel + "|" + em + "|" + soundex(lastName);
34	        try {
35	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
36	            StringBuilder sb = new StringBuilder(digest.length * 2);
37	            for (byte b : digest) {
38	                sb.append(String.format("%02x", b));
39	            }
40	            return sb.toString();
41	        }
42	        catch (NoSuchAlgorithmException ex) {
43	            throw new IllegalStateException(ex);
44	        }
45	    }
46	
47	    /**
48	     * American Soundex of a name: the first letter (upper-cased) followed by three digits encoding
49	     * the remaining consonant sounds, zero-padded to length four. Adjacent letters coding to the
50	     * same digit collapse to one; vowels (and {@code y}) reset the run while {@code h} and {@code w}
51	     * are transparent. Returns {@code ""} for a null or letter-free value.
52	     */
53	    public static String soundex(String value) {
54	        if (value == null) {
55	            return "";
56	        }
57	        StringBuilder letters = new StringBuilder();
58	        for (int i = 0; i < value.length(); i++) {
59	            char c = value.charAt(i);
60	            if (Character.isLetter(c)) {
61	                letters.append(Character.toUpperCase(c));
62	            }
63	        }
64	        if (letters.length() == 0) {
65	            return "";
66	        }
67	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
68	        char prevDigit = soundexDigit(letters.charAt(0));
69	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
70	            char c = letters.charAt(i);
71	            char digit = soundexDigit(c);
72	            if (digit != '0' && digit != prevDigit) {
73	                code.append(digit);
74	            }
75	            if (c != 'H' && c != 'W') {
76	                prevDigit = digit; // vowels reset the run; H and W are transparent
77	            }
78	        }
79	        while (code.length() < 4) {
80	            code.append('0');
81	        }
82	        return code.toString();
83	    }
84	
85	    private static char soundexDigit(char c) {
86	        switch (c) {
87	            case 'B': case 'F': case 'P': case 'V':
88	                return '1';
89	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
90	                return '2';
91	            case 'D': case 'T':
92	                return '3';
93	            case 'L':
94	                return '4';
95	            case 'M': case 'N':
96	                return '5';
97	            case 'R':
98	                return '6';
99	            default:
100	                return '0';
101	        }
102	    }
103	
104	    /**
105	     * The hash segment of an owner's {@code '<REGION>-<HASH8>'} customer code: the first 8
106	     * upper-case hex characters of SHA-256 over the normalised telephone concatenated with the
107	     * last name. The telephone is expected to already be in E.164 form (as stored).
108	     */
109	    public static String customerHash(String normalizedTelephone, String lastName) {
110	        String tel = normalizedTelephone == null ? "" : normalizedTelephone;
111	        String last = lastName == null ? "" : lastName;
112	        try {
113	            byte[] digest = MessageDigest.getInstance("SHA-256")
114	                .digest((tel + last).getBytes(StandardCharsets.UTF_8));
115	            StringBuilder sb = new StringBuilder(8);
116	            for (int i = 0; i < 4; i++) {
117	                sb.append(String.format("%02X", digest[i]));
118	            }
119	            return sb.toString();
120	        }
121	        catch (NoSuchAlgorithmException ex) {
122	            throw new IllegalStateException(ex);
123	        }
124	    }
125	
126	    /**
127	     * The household's stable, deterministic identifier: the first 12 upper-case hex characters of
128	     * SHA-256 over {@code normalizedLastName + '|' + postcode}. Owners sharing a last name and
129	     * postcode therefore resolve to the same value automatically, regardless of creation order or
130	     * whether they opted into {@code sharesHousehold}. Returns {@code null} when no postcode is
131	     * given, since a household is keyed on (last name, postcode) and cannot form without one.
132	     */
133	    public static String householdId(String lastName, String postcode) {
134	        if (postcode == null || postcode.isBlank()) {
135	            return null;
136	        }
137	        try {
138	            String key = normalizeName(lastName) + "|" + postcode;
139	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
140	            StringBuilder sb = new StringBuilder(12);
141	            for (int i = 0; i < 6; i++) {
142	                sb.append(String.format("%02X", digest[i]));
143	            }
144	            return sb.toString();
145	        }
146	        catch (NoSuchAlgorithmException ex) {
147	            throw new IllegalStateException(ex);
148	        }
149	    }
150	
151	    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
152	    static String normalizeName(String value) {
153	        if (value == null) {
154	            return "";
155	        }
156	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
157	    }
158	}
