1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.mapper.FiscalYear;
7	import org.springframework.samples.petclinic.mapper.MembershipLevel;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Emits an audit line to the dedicated {@code AUDIT} logger for a successfully created owner,
12	 * carrying the owner id, the {@code customerCode}, the {@code registrationDate}, the
13	 * {@code membershipNumber} and the derived membership points and level. Runs after the owner has
14	 * been saved (so the generated id is available) and before the response is sent.
15	 */
16	public class LogOwnerAudit {
17	
18	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
19	
20	    public void service(@Val Owner owner) {
21	        String membershipNumber = owner.getCustomerCode() + "-M"
22	                + String.format("%02d", FiscalYear.yearSegment(owner.getRegistrationDate()));
23	        AUDIT.info(
24	                "Owner created: id={} customerCode={} registrationDate={} membershipNumber={} "
25	                        + "membershipPoints={} membershipLevel={}",
26	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), membershipNumber,
27	                MembershipLevel.points(owner), MembershipLevel.of(owner));
28	    }
29	}
