1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Immutable structured audit event emitted when an owner is created.
5	 *
6	 * <p>Serialised to a compact JSON object
7	 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}} and written to the
8	 * {@code AUDIT} logger. {@code seq} is a monotonically increasing integer across creates and
9	 * {@code customerCode} holds the owner's current primary identifier (see
10	 * {@link org.springframework.samples.petclinic.mapper.PrimaryIdentifier}), so a later switch of the
11	 * primary identifier to a {@code memberId} carries through here without changing this event.
12	 *
13	 * <p>The record is deeply immutable (all components are values), so once emitted the event cannot be
14	 * altered.
15	 */
16	public record OwnerCreatedEvent(int seq, Integer ownerId, String customerCode, int membershipLevel,
17	        String event) {
18	
19	    /** The marker every create event carries. */
20	    public static final String OWNER_CREATED = "OWNER_CREATED";
21	
22	    /** Compact JSON rendering with fields in the documented order. */
23	    public String toJson() {
24	        return "{\"seq\":" + this.seq
25	                + ",\"ownerId\":" + this.ownerId
26	                + ",\"customerCode\":" + jsonString(this.customerCode)
27	                + ",\"membershipLevel\":" + this.membershipLevel
28	                + ",\"event\":" + jsonString(this.event)
29	                + "}";
30	    }
31	
32	    /** A JSON string literal for {@code value}, or {@code null} when absent. */
33	    private static String jsonString(String value) {
34	        if (value == null) {
35	            return "null";
36	        }
37	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
38	        for (int i = 0; i < value.length(); i++) {
39	            char c = value.charAt(i);
40	            switch (c) {
41	                case '"' -> sb.append("\\\"");
42	                case '\\' -> sb.append("\\\\");
43	                case '\n' -> sb.append("\\n");
44	                case '\r' -> sb.append("\\r");
45	                case '\t' -> sb.append("\\t");
46	                default -> {
