package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Step of {@code POST /api/owners}: rejects the request 409 when the owner's city already contains
 * 50 or more owners. City is compared exactly, consistent with the per-city sequence in
 * {@link AssignCustomerCode}. Runs before {@link BuildOwner} so no owner is persisted on conflict.
 */
public class RequireCityCapacity {

    /** Maximum number of owners permitted in a single city. */
    private static final int CITY_CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        long count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city.equals(existing.getCity())) {
                count++;
            }
        }
        if (count >= CITY_CAPACITY) {
            throw new CityAtCapacityException(city);
        }
    }
}

package org.springframework.samples.petclinic.mapper;

/**
 * Computes an owner's {@code checkDigit} &mdash; a single Luhn check digit (0-9) over the digits
 * contained in the owner's {@code customerCode}.
 *
 * <p>Non-digit characters (the region letters and the separator in {@code '<REGION>-<HASH8>'}, and
 * the {@code A-F} hex letters of the hash) are ignored. The digits are processed right-to-left,
 * doubling every second digit starting with the rightmost;
 * a doubled value above nine has nine subtracted. The check digit is the amount that brings the
 * running sum up to the next multiple of ten.
 */
public final class CheckDigit {

    private CheckDigit() {
    }

    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
    public static int of(String s) {
        int sum = 0;
        boolean dbl = true;
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}

